content:
:root {
  --bg-primary: #0b0f19;
  --bg-secondary: #131b2e;
  --bg-card: rgba(19, 27, 46, 0.75);
  --bg-card-hover: rgba(28, 39, 66, 0.85);
  --accent-cyan: #00f2fe;
  --accent-blue: #4facfe;
  --accent-purple: #8a2be2;
  --text-main: #f1f5f9;
  --text-muted: #94a3b8;
  --text-sub: #cbd5e1;
  --border-color: rgba(255, 255, 255, 0.1);
  --border-focus: rgba(0, 242, 254, 0.5);
  --shadow-glow: 0 0 20px rgba(0, 242, 254, 0.2);
  --radius-lg: 16px;
  --radius-md: 10px;
  --radius-sm: 6px;
  --font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-primary);
  color: var(--text-main);
  min-height: 100vh;
  overflow-x: hidden;
  background-image: 
    radial-gradient(circle at 15% 20%, rgba(79, 172, 254, 0.12) 0%, transparent 40%),
    radial-gradient(circle at 85% 80%, rgba(138, 43, 226, 0.12) 0%, transparent 40%),
    linear-gradient(to bottom, #090d16, #0d1322);
}

/* アプリ全体コンテナ */
.app-container {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 16px 20px 24px;
}

/* ヘッダー */
.header {
  text-align: center;
  padding: 12px 16px 20px;
}

.header-title {
  font-size: 1.85rem;
  font-weight: 800;
  letter-spacing: -0.5px;
  background: linear-gradient(135deg, #ffffff 30%, var(--accent-cyan) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  margin-bottom: 6px;
}

.header-desc {
  font-size: 0.95rem;
  color: var(--text-muted);
  font-weight: 400;
  line-height: 1.5;
}

/* メインコンテンツレイアウト (キャンバスと操作パネル) */
@media (min-width: 860px) {
  .app-container {
    display: grid;
    grid-template-columns: 1fr 340px;
    grid-template-rows: auto 1fr;
    gap: 20px;
    height: 100vh;
    padding: 20px 24px;
  }

  .header {
    grid-column: 1 / -1;
    text-align: left;
    padding: 4px 0 12px;
  }

  .canvas-area {
    height: 100% !important;
    min-height: 520px;
  }

  .control-panel {
    height: 100%;
    overflow-y: auto;
  }
}

/* 3Dキャンバス表示エリア */
.canvas-area {
  position: relative;
  flex: 1;
  min-height: 400px;
  background: var(--bg-card);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-color);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4), inset 0 0 1px 1px rgba(255, 255, 255, 0.05);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.canvas-wrapper {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  touch-action: none;
  cursor: grab;
  outline: none;
}

.canvas-wrapper:active {
  cursor: grabbing;
}

.canvas-wrapper:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: -2px;
  box-shadow: inset var(--shadow-glow);
}

.canvas-overlay-hint {
  position: absolute;
  top: 16px;
  left: 16px;
  padding: 8px 14px;
  background: rgba(11, 15, 25, 0.65);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 20px;
  font-size: 0.8rem;
  color: var(--text-sub);
  pointer-events: none;
  display: flex;
  align-items: center;
  gap: 6px;
  z-index: 5;
  user-select: none;
}

.stats-badge {
  position: absolute;
  bottom: 16px;
  left: 16px;
  padding: 6px 12px;
  background: rgba(11, 15, 25, 0.7);
  backdrop-filter: blur(8px);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: var(--radius-sm);
  font-size: 0.75rem;
  color: var(--accent-cyan);
  font-family: monospace;
  pointer-events: none;
  z-index: 5;
  display: flex;
  align-items: center;
  gap: 8px;
}

/* コントロールパネル */
.control-panel {
  background: var(--bg-card);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-color);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
  margin-top: 16px;
}

@media (min-width: 860px) {
  .control-panel {
    margin-top: 0;
  }
}

.panel-title {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-main);
  letter-spacing: -0.3px;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 12px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.control-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.control-label {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-muted);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

/* スライダー設定 */
.control-slider {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 6px;
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.15);
  outline: none;
  transition: background 0.2s, box-shadow 0.2s;
  cursor: pointer;
}

.control-slider:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 4px;
  box-shadow: var(--shadow-glow);
}

.control-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--accent-cyan);
  box-shadow: 0 0 10px var(--accent-cyan);
  cursor: pointer;
  transition: transform 0.15s ease, background-color 0.15s ease;
}

.control-slider::-webkit-slider-thumb:hover {
  transform: scale(1.15);
  background: #ffffff;
}

.control-slider::-moz-range-thumb {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  border: none;
  background: var(--accent-cyan);
  box-shadow: 0 0 10px var(--accent-cyan);
  cursor: pointer;
}

/* トグルスイッチ */
.toggle-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  background: rgba(255, 255, 255, 0.03);
  border-radius: var(--radius-md);
  border: 1px solid rgba(255, 255, 255, 0.05);
  cursor: pointer;
  user-select: none;
  transition: background-color 0.2s, box-shadow 0.2s, border-color 0.2s;
  outline: none;
}

.toggle-container:hover {
  background: rgba(255, 255, 255, 0.06);
}

.toggle-container:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
  border-color: var(--border-focus);
  box-shadow: var(--shadow-glow);
}

.toggle-label {
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--text-sub);
}

/* カラーパレット選択 */
.color-list {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 8px;
  padding-top: 4px;
}

.color-btn {
  aspect-ratio: 1;
  border-radius: 50%;
  border: 2px solid transparent;
  cursor: pointer;
  outline: none;
  transition: transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.2s ease, border-color 0.2s ease;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.color-btn:hover {
  transform: scale(1.15);
}

.color-btn:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 3px;
  box-shadow: var(--shadow-glow);
}

.color-btn-active {
  border-color: #ffffff;
  transform: scale(1.12);
  box-shadow: 0 0 14px currentColor, var(--shadow-glow);
}

.color-btn-active::after {
  content: '';
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background-color: #ffffff;
}

/* ボタングループとアクションボタン */
.button-row {
  display: flex;
  gap: 10px;
  margin-top: auto;
  padding-top: 10px;
}

.control-btn {
  flex: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 16px;
  border-radius: var(--radius-md);
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
  border: none;
  outline: none;
  user-select: none;
}

.control-btn:active {
  transform: scale(0.97);
}

.control-btn:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
  box-shadow: var(--shadow-glow);
}

.control-btn-primary {
  background: linear-gradient(135deg, var(--accent-cyan) 0%, var(--accent-blue) 100%);
  color: #0b0f19;
  box-shadow: 0 4px 14px rgba(0, 242, 254, 0.3);
}

.control-btn-primary:hover {
  box-shadow: 0 6px 20px rgba(0, 242, 254, 0.45);
  filter: brightness(1.08);
}

.control-btn-secondary {
  background: rgba(255, 255, 255, 0.08);
  color: var(--text-main);
  border: 1px solid rgba(255, 255, 255, 0.12);
}

.control-btn-secondary:hover {
  background: rgba(255, 255, 255, 0.14);
  border-color: rgba(255, 255, 255, 0.2);
}

/* スマホ小型端末向け微調整 */
@media (max-width: 480px) {
  .app-container {
    padding: 12px 14px 20px;
  }

  .header-title {
    font-size: 1.5rem;
  }

  .canvas-area {
    min-height: 320px;
  }

  .control-panel {
    padding: 18px 16px;
    gap: 16px;
  }

  .color-list {
    gap: 6px;
  }
}

/* モーション低減設定への配慮 */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }

  .color-btn:hover,
  .color-btn-active,
  .control-btn:active,
  .control-slider::-webkit-slider-thumb:hover {
    transform: none;
  }
}

/* ハイコントラスト・強制カラーモードへの配慮 */
@media (forced-colors: active) {
  .control-slider::-webkit-slider-thumb,
  .control-slider::-moz-range-thumb {
    border: 2px solid ButtonText;
  }

  .color-btn-active {
    outline: 2px solid Highlight;
  }

  .control-btn {
    border: 1px solid ButtonText;
  }
}

/**
 * 3D立方体のレンダリングおよび動作設定を管理するインターフェース
 */
export interface CubeConfig {
  /** 自動回転の有効/無効フラグ */
  autoRotate: boolean;
  /** 立方体の自動回転速度倍率 */
  rotateSpeed: number;
  /** ワイヤーフレーム描画モードのフラグ */
  wireframe: boolean;
  /** 立方体の基準カラー（Hex形式文字列） */
  mainColor: string;
  /** マテリアルの表面粗さ（0.0: 完全鏡面 〜 1.0: 拡散反射） */
  roughness: number;
  /** マテリアルの金属度（0.0: 非金属 〜 1.0: 完全金属） */
  metalness: number;
}

/**
 * 立方体コントロールパネルコンポーネントのPropsインターフェース
 */
export interface CubeControlProps {
  /** 現在の立方体設定 */
  config: CubeConfig;
  /** 設定を部分更新するためのコールバック関数 */
  onConfigChange: (newConfig: Partial<CubeConfig>) => void;
  /** カメラおよび立方体の回転視点を初期位置に戻すコールバック関数 */
  onResetView: () => void;
  /** 立方体のすべての設定を初期値に戻すコールバック関数（任意） */
  onResetConfig?: () => void;
}

/**
 * カラーパレット選択肢のデータ定義
 */
export interface ColorPreset {
  /** プリセットの一意識別子 */
  id: string;
  /** プリセットの表示名 */
  name: string;
  /** カラーコード（Hex形式） */
  color: string;
}

/**
 * ユーザーが選択可能な推奨カラープリセット一覧
 */
export const COLOR_PRESETS: ColorPreset[] = [
  { id: 'blue', name: 'シアンブルー', color: '#00f2fe' },
  { id: 'purple', name: 'ネオンパープル', color: '#8a2be2' },
  { id: 'emerald', name: 'エメラルド', color: '#10b981' },
  { id: 'ruby', name: 'ルビーレッド', color: '#f43f5e' },
  { id: 'gold', name: 'サンシャインゴールド', color: '#fbbf24' },
  { id: 'cyber', name: 'サイバーピンク', color: '#ec4899' },
];

/**
 * 立方体の初期設定デフォルト値
 */
export const DEFAULT_CUBE_CONFIG: CubeConfig = {
  autoRotate: true,
  rotateSpeed: 1.0,
  wireframe: false,
  mainColor: '#00f2fe',
  roughness: 0.2,
  metalness: 0.15,
};

import { useEffect, useRef, useCallback } from 'react';
import * as THREE from 'three';
import { CubeConfig } from '../types';

interface CubeCanvasProps {
  config: CubeConfig;
  resetTrigger: number;
}

const CubeCanvas = ({ config, resetTrigger }: CubeCanvasProps) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const cubeRef = useRef<THREE.Mesh | null>(null);
  const sceneRef = useRef<THREE.Scene | null>(null);
  const cameraRef = useRef<THREE.PerspectiveCamera | null>(null);
  const rendererRef = useRef<THREE.WebGLRenderer | null>(null);

  // 最新のconfigを常に参照するためのref（stale closure対策）
  const configRef = useRef<CubeConfig>(config);
  configRef.current = config;

  // ドラッグ操作用の参照値
  const isDraggingRef = useRef(false);
  const prevPointerPositionRef = useRef({ x: 0, y: 0 });
  const angularVelocityRef = useRef({ x: 0, y: 0 });

  // DOM直接更新用ref（毎フレームの不要な再レンダリングを回避）
  const statsXRef = useRef<HTMLSpanElement>(null);
  const statsYRef = useRef<HTMLSpanElement>(null);
  const statsFpsRef = useRef<HTMLSpanElement>(null);

  // 視点リセット処理
  const handleReset = useCallback(() => {
    if (!cubeRef.current || !cameraRef.current) return;
    cubeRef.current.rotation.set(0.4, 0.6, 0);
    angularVelocityRef.current = { x: 0, y: 0 };
    cameraRef.current.position.set(0, 0, 5);

    if (statsXRef.current) statsXRef.current.textContent = 'X: 23°';
    if (statsYRef.current) statsYRef.current.textContent = 'Y: 34°';
  }, []);

  // 外部からのリセットトリガー監視
  useEffect(() => {
    if (resetTrigger > 0) {
      handleReset();
    }
  }, [resetTrigger, handleReset]);

  // Three.js シーンの初期化
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const width = container.clientWidth || 300;
    const height = container.clientHeight || 300;

    // シーン
    const scene = new THREE.Scene();
    sceneRef.current = scene;

    // カメラ
    const camera = new THREE.PerspectiveCamera(45, width / height, 0.1, 100);
    camera.position.set(0, 0, 5);
    cameraRef.current = camera;

    // レンダラー
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, powerPreference: 'high-performance' });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    rendererRef.current = renderer;
    container.appendChild(renderer.domElement);

    // 立方体ジオメトリ & マテリアル
    const geometry = new THREE.BoxGeometry(2, 2, 2, 8, 8, 8);
    const materials: THREE.MeshStandardMaterial[] = [];

    // 面ごとに微妙なトーン変化を持たせたマテリアル群
    const baseColor = new THREE.Color(configRef.current.mainColor);
    const faceLightAdjustments = [1.0, 0.85, 1.15, 0.7, 0.95, 0.75];

    for (let i = 0; i < 6; i++) {
      const faceColor = baseColor.clone().multiplyScalar(faceLightAdjustments[i]);
      materials.push(
        new THREE.MeshStandardMaterial({
          color: faceColor,
          roughness: configRef.current.roughness,
          metalness: 0.15,
          wireframe: configRef.current.wireframe,
        })
      );
    }

    const cube = new THREE.Mesh(geometry, materials);
    cube.rotation.set(0.4, 0.6, 0);
    cube.castShadow = true;
    cube.receiveShadow = true;
    scene.add(cube);
    cubeRef.current = cube;

    // エッジハイライト（スタイリッシュなライン枠）
    const edges = new THREE.EdgesGeometry(geometry);
    const lineMaterial = new THREE.LineBasicMaterial({
      color: 0xffffff,
      transparent: true,
      opacity: 0.25,
      linewidth: 1,
    });
    const edgeLines = new THREE.LineSegments(edges, lineMaterial);
    cube.add(edgeLines);

    // 照明配置
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.8);
    scene.add(ambientLight);

    const mainLight = new THREE.DirectionalLight(0xffffff, 1.6);
    mainLight.position.set(5, 7, 6);
    mainLight.castShadow = true;
    scene.add(mainLight);

    const rimLight = new THREE.PointLight(0x00f2fe, 2.5, 15);
    rimLight.position.set(-5, -4, -4);
    scene.add(rimLight);

    const accentLight = new THREE.PointLight(0x8a2be2, 2.0, 15);
    accentLight.position.set(4, -4, 4);
    scene.add(accentLight);

    // アニメーションループ & FPS計測
    let frameId: number;
    let lastTime = performance.now();
    let frameCount = 0;
    let fpsTime = performance.now();

    const animate = (time: number) => {
      frameId = requestAnimationFrame(animate);

      const delta = Math.min((time - lastTime) / 1000, 0.1);
      lastTime = time;

      // FPS計測・回転角度更新（DOM参照で直接更新しキャンバス再描画を抑止）
      frameCount++;
      if (time - fpsTime >= 500) {
        const currentFps = Math.round((frameCount * 1000) / (time - fpsTime));
        const rotXDeg = Math.round((((cube.rotation.x * 180) / Math.PI) % 360 + 360) % 360);
        const rotYDeg = Math.round((((cube.rotation.y * 180) / Math.PI) % 360 + 360) % 360);

        if (statsXRef.current) statsXRef.current.textContent = `X: ${rotXDeg}°`;
        if (statsYRef.current) statsYRef.current.textContent = `Y: ${rotYDeg}°`;
        if (statsFpsRef.current) statsFpsRef.current.textContent = `FPS: ${currentFps}`;

        frameCount = 0;
        fpsTime = time;
      }

      // 自動回転（configRefから最新値を参照）
      const currentConfig = configRef.current;
      if (currentConfig.autoRotate && !isDraggingRef.current) {
        cube.rotation.y += delta * 0.7 * currentConfig.rotateSpeed;
        cube.rotation.x += delta * 0.35 * currentConfig.rotateSpeed;
      }

      // 慣性回転（ドラッグ後の余韻）
      if (!isDraggingRef.current) {
        cube.rotation.y += angularVelocityRef.current.x;
        cube.rotation.x += angularVelocityRef.current.y;
        angularVelocityRef.current.x *= 0.94;
        angularVelocityRef.current.y *= 0.94;
      }

      renderer.render(scene, camera);
    };

    frameId = requestAnimationFrame(animate);

    // リサイズ監視
    const resizeObserver = new ResizeObserver((entries) => {
      for (const entry of entries) {
        const { width: newWidth, height: newHeight } = entry.contentRect;
        if (newWidth > 0 && newHeight > 0) {
          camera.aspect = newWidth / newHeight;
          camera.updateProjectionMatrix();
          renderer.setSize(newWidth, newHeight);
        }
      }
    });

    resizeObserver.observe(container);

    // ホイールズーム操作（passive: false で明示的登録）
    const handleWheel = (e: WheelEvent) => {
      e.preventDefault();
      if (!cameraRef.current) return;
      const zoomDelta = e.deltaY * 0.003;
      const newZ = cameraRef.current.position.z + zoomDelta;
      // ズーム範囲の制限 (2.5 ~ 9.0)
      cameraRef.current.position.z = Math.min(Math.max(newZ, 2.5), 9.0);
    };

    container.addEventListener('wheel', handleWheel, { passive: false });

    // クリーンアップ
    return () => {
      cancelAnimationFrame(frameId);
      resizeObserver.disconnect();
      container.removeEventListener('wheel', handleWheel);
      if (renderer.domElement && container.contains(renderer.domElement)) {
        container.removeChild(renderer.domElement);
      }
      geometry.dispose();
      edges.dispose();
      lineMaterial.dispose();
      materials.forEach((m) => m.dispose());
      renderer.dispose();
    };
  }, []);

  // マテリアルと設定の更新（カラー、ワイヤーフレーム、粗さ）
  useEffect(() => {
    if (!cubeRef.current) return;
    const materials = cubeRef.current.material;
    const baseColor = new THREE.Color(config.mainColor);
    const faceLightAdjustments = [1.0, 0.85, 1.15, 0.7, 0.95, 0.75];

    if (Array.isArray(materials)) {
      materials.forEach((mat, idx) => {
        if (mat instanceof THREE.MeshStandardMaterial) {
          mat.color = baseColor.clone().multiplyScalar(faceLightAdjustments[idx % 6]);
          mat.wireframe = config.wireframe;
          mat.roughness = config.roughness;
          mat.needsUpdate = true;
        }
      });
    }
  }, [config.mainColor, config.wireframe, config.roughness]);

  // ポインタードラッグ操作（マウス & タッチ共通）
  const handlePointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    isDraggingRef.current = true;
    prevPointerPositionRef.current = { x: e.clientX, y: e.clientY };
    angularVelocityRef.current = { x: 0, y: 0 };
    if (e.currentTarget) {
      e.currentTarget.setPointerCapture(e.pointerId);
    }
  };

  const handlePointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!isDraggingRef.current || !cubeRef.current) return;

    const deltaX = e.clientX - prevPointerPositionRef.current.x;
    const deltaY = e.clientY - prevPointerPositionRef.current.y;

    const rotSpeed = 0.007;
    const deltaRotY = deltaX * rotSpeed;
    const deltaRotX = deltaY * rotSpeed;

    cubeRef.current.rotation.y += deltaRotY;
    cubeRef.current.rotation.x += deltaRotX;

    angularVelocityRef.current = {
      x: deltaRotY * 0.7,
      y: deltaRotX * 0.7,
    };

    prevPointerPositionRef.current = { x: e.clientX, y: e.clientY };
  };

  const handlePointerUp = (e: React.PointerEvent<HTMLDivElement>) => {
    isDraggingRef.current = false;
    if (e.currentTarget && e.currentTarget.hasPointerCapture(e.pointerId)) {
      e.currentTarget.releasePointerCapture(e.pointerId);
    }
  };

  return (
    <div className="canvas-area">
      <div
        ref={containerRef}
        className="canvas-wrapper"
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerCancel={handlePointerUp}
      />
      <div className="canvas-overlay-hint">
        <span>🖱️ ドラッグで回転 / スクロールで拡大縮小</span>
      </div>
      <div className="stats-badge">
        <span ref={statsXRef}>X: 23°</span>
        <span ref={statsYRef}>Y: 34°</span>
        <span ref={statsFpsRef}>FPS: 60</span>
      </div>
    </div>
  );
};

