import { useState, useCallback, useEffect } from 'react';
import CubeCanvas from './components/CubeCanvas';
import ControlPanel from './components/ControlPanel';
import { CubeConfig, DEFAULT_CUBE_CONFIG } from './types';

const App = () => {
  const [cubeConfig, setCubeConfig] = useState<CubeConfig>(DEFAULT_CUBE_CONFIG);
  const [resetTrigger, setResetTrigger] = useState(0);

  const handleConfigChange = useCallback((newConfig: Partial<CubeConfig>) => {
    setCubeConfig((prev) => ({ ...prev, ...newConfig }));
  }, []);

  const handleResetView = useCallback(() => {
    setResetTrigger((prev) => prev + 1);
  }, []);

  const handleResetConfig = useCallback(() => {
    setCubeConfig(DEFAULT_CUBE_CONFIG);
    handleResetView();
  }, [handleResetView]);

  // キーボードショートカットの登録（Space: 回転トグル, R: 視点リセット, Shift+R: 全設定初期化）
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement | null;
      if (
        target &&
        (target.tagName === 'INPUT' ||
          target.tagName === 'TEXTAREA' ||
          target.isContentEditable)
      ) {
        return;
      }

      if (e.code === 'Space') {
        e.preventDefault();
        setCubeConfig((prev) => ({ ...prev, autoRotate: !prev.autoRotate }));
      } else if (e.key === 'r' || e.key === 'R') {
        if (e.shiftKey) {
          handleResetConfig();
        } else {
          handleResetView();
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [handleResetConfig, handleResetView]);

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="header-title">3D Cube Interactive Viewer</h1>
        <p className="header-desc">
          Three.jsを活用した直感的な3D立体ビューワー。ドラッグやタッチで回転、ズーム、質感・スピードをリアルタイムにカスタマイズできます。
        </p>
      </header>

      <main style={{ display: 'contents' }}>
        <CubeCanvas config={cubeConfig} resetTrigger={resetTrigger} />

        <ControlPanel
          config={cubeConfig}
          onConfigChange={handleConfigChange}
          onResetView={handleResetView}
          onResetConfig={handleResetConfig}
        />
      </main>
    </div>
  );
};

export default App;
